from contextvars import ContextVar
from typing import Any, Optional

# Set by the DUT test runner before each _send_user_message call so that all
# LLM traces within one test-case run share the original (pre-counter) sender_id
# as the Langfuse session ID, rather than the per-step tracker sender_id
# (step_sender_id = f"{test_case_sender_id}_{step_index}").
langfuse_session_id_override: ContextVar[Optional[str]] = ContextVar(
    "langfuse_session_id_override", default=None
)


def get_langfuse_session_id(tracker: Any) -> str:
    """Return the Langfuse session ID for the given tracker.

    During normal operation returns tracker.sender_id. During DUT test runs the
    DUT runner sets langfuse_session_id_override so that all per-step LLM calls
    are grouped under the original test-case sender_id.
    """
    override = langfuse_session_id_override.get()
    return override if override is not None else tracker.sender_id
